GRANT INSERT ON payroll_preparations TO authenticated;
SET ROLE authenticated;
SELECT set_config('test.actor','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',false);
DO $$
DECLARE d uuid:='11111111-1111-4111-8111-111111111111';f uuid:='33333333-3333-4333-8333-333333333333';w uuid:='55555555-5555-4555-8555-555555555555';
 rows jsonb; period jsonb; item record; request uuid:=gen_random_uuid(); rev integer; failed boolean; payrows jsonb; prep jsonb;
BEGIN
 SELECT jsonb_agg(jsonb_build_object('worker_id',w,'work_date',day::date,'normal_hours',CASE WHEN day::date='2026-11-01' THEN 32 WHEN day::date='2026-11-02' THEN 17.5824 ELSE 0 END,
  'overtime_hours',0,'entry_source','excel','source_filename','source.xlsx','source_references',jsonb_build_array('Source!22','Source!90'))) INTO rows FROM generate_series('2026-11-01'::date,'2026-11-15'::date,interval '1 day') day;
 period:=save_employee_attendance(d,f,'2026-11-01','2026-11-15',0,rows,'save',gen_random_uuid());
 IF (SELECT count(*) FROM employee_attendance_records WHERE period_id=(period->>'id')::uuid AND needs_review)<>2 THEN RAISE EXCEPTION 'Expected two pending reviews'; END IF;
 SELECT * INTO item FROM employee_attendance_records WHERE period_id=(period->>'id')::uuid AND work_date='2026-11-02';
 IF item.normal_hours<>17.5824 OR (item.original_hours->>'normal_hours')::numeric<>17.5824 THEN RAISE EXCEPTION 'Original precision lost'; END IF;
 failed:=false;
 BEGIN PERFORM save_employee_attendance(d,f,'2026-11-01','2026-11-15',(period->>'revision')::int,rows,'validate',gen_random_uuid());
 EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE '%anomalies%' THEN RAISE; END IF; failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Unreviewed validation allowed'; END IF;
 failed:=false;
 BEGIN INSERT INTO payroll_preparations(domain_id,farm_id,start_date,rows) VALUES(d,f,'2026-11-01',jsonb_build_array(jsonb_build_object('worker_id',w,'source','manual')));
 EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE '%Paie bloquée%' THEN RAISE; END IF; failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Manual payroll bypass allowed'; END IF;
 failed:=false;
 BEGIN PERFORM review_employee_attendance(d,(period->>'id')::uuid,(period->>'revision')::int,w,'2026-11-01','other','','confirm',gen_random_uuid());
 EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE '%motif%' THEN RAISE; END IF; failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Missing reason accepted'; END IF;
 PERFORM set_config('test.allowed','no',true);failed:=false;
 BEGIN PERFORM review_employee_attendance(d,(period->>'id')::uuid,(period->>'revision')::int,w,'2026-11-01','duplicate','checked','confirm',gen_random_uuid());
 EXCEPTION WHEN insufficient_privilege THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Unauthorized review allowed'; END IF;
 PERFORM set_config('test.allowed','yes',true);
 failed:=false;
 BEGIN PERFORM review_employee_attendance('22222222-2222-4222-8222-222222222222',(period->>'id')::uuid,(period->>'revision')::int,w,'2026-11-01','duplicate','checked','confirm',gen_random_uuid());
 EXCEPTION WHEN insufficient_privilege THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Cross-client review allowed'; END IF;
 failed:=false;
 BEGIN PERFORM review_employee_attendance(d,(period->>'id')::uuid,(period->>'revision')::int,w,'2026-11-01','advance','','confirm',gen_random_uuid());
 EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE '%avance%' THEN RAISE; END IF; failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Advance treated as hours'; END IF;
 rev:=(period->>'revision')::int;
 period:=review_employee_attendance(d,(period->>'id')::uuid,rev,w,'2026-11-01','other','Valeur vérifiée dans la source','confirm',request);
 IF (review_employee_attendance(d,(period->>'id')::uuid,rev,w,'2026-11-01','other','Valeur vérifiée dans la source','confirm',request)->>'revision')::int<>(period->>'revision')::int THEN RAISE EXCEPTION 'Review replay changed revision'; END IF;
 period:=review_employee_attendance(d,(period->>'id')::uuid,(period->>'revision')::int,w,'2026-11-02','other','Précision confirmée','confirm',gen_random_uuid());
 period:=save_employee_attendance(d,f,'2026-11-01','2026-11-15',(period->>'revision')::int,rows,'validate',gen_random_uuid());
 payrows:=jsonb_build_array(jsonb_build_object('worker_id',w,'source','attendance','normal_hours',49.5824,'overtime_hours',0,'normal_rate',10,'overtime_rate',0,'bonuses',0,'advance',0,'other_deductions',0,'deductions_confirmed',true));
 prep:=save_payroll_preparation(d,f,'2026-11-01','2026-11-15','88888888-8888-4888-8888-888888888888','2026-11-15',(period->>'revision')::int,0,payrows,'save',gen_random_uuid());
 IF (prep->'rows'->0->>'normal_hours')::numeric<>49.5824 OR (prep->'rows'->0->>'base_amount')::numeric<>495.82 THEN RAISE EXCEPTION 'Reviewed hours lost on payroll'; END IF;
 period:=save_employee_attendance(d,f,'2026-11-01','2026-11-15',(period->>'revision')::int,rows,'reopen',gen_random_uuid());
 rows:=jsonb_set(rows,'{0,normal_hours}','16');
 period:=save_employee_attendance(d,f,'2026-11-01','2026-11-15',(period->>'revision')::int,rows,'save',gen_random_uuid());
 SELECT * INTO item FROM employee_attendance_records WHERE period_id=(period->>'id')::uuid AND work_date='2026-11-01';
 IF NOT item.needs_review OR item.review_status<>'pending' OR (item.original_hours->>'normal_hours')::numeric<>32 THEN RAISE EXCEPTION 'Edit did not invalidate review or lost original'; END IF;
 period:=review_employee_attendance(d,(period->>'id')::uuid,(period->>'revision')::int,w,'2026-11-01','duplicate','Doublon corrigé','resolve',gen_random_uuid());
 SELECT * INTO item FROM employee_attendance_records WHERE period_id=(period->>'id')::uuid AND work_date='2026-11-01';
 IF item.needs_review OR item.review_status<>'resolved' OR jsonb_array_length(item.review_history)<>2 THEN RAISE EXCEPTION 'Resolution audit missing'; END IF;
 period:=save_employee_attendance(d,f,'2026-11-01','2026-11-15',(period->>'revision')::int,rows,'validate',gen_random_uuid());
 payrows:=jsonb_set(payrows,'{0,normal_hours}','33.5824');
 payrows:=jsonb_set(payrows,'{0,tax_context}',(SELECT ctx FROM jsonb_array_elements(payroll_net_context(d,f,'2026-11-01')) ctx WHERE ctx->>'worker_id'=w::text));
 prep:=save_payroll_preparation(d,f,'2026-11-01','2026-11-15','88888888-8888-4888-8888-888888888888','2026-11-15',(period->>'revision')::int,(prep->>'revision')::int,payrows,'validate',gen_random_uuid());
 IF (SELECT hours_worked FROM payslips WHERE period_id=(prep->>'payroll_period_id')::uuid)<>33.5824 THEN RAISE EXCEPTION 'Payslip hours rounded'; END IF;
END $$;
RESET ROLE;
